export function HoverCard({trigger,children}:{trigger:React.ReactElement;children:React.ReactNode}){return <H.Root><H.Trigger asChild>{trigger}</H.Trigger><H.Portal><H.Content sideOffset={8} className="a-popup w-72 p-5">{children}</H.Content></H.Portal></H.Root>}
